css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .96); position: relative; }
.loader span { position: absolute; width: 34%; height: 30%; clip-path: polygon(25% 0%, 75% 0%, 100% 50%, 75% 100%, 25% 100%, 0% 50%); background: var(--accent); animation: comb calc(var(--loader-speed) * 1.9) ease-in-out infinite; }
.loader span:nth-child(1) { left: 33%; top: 35%; background: var(--accent-2); animation-delay: 0s; }
.loader span:nth-child(2) { left: 33%; top: 5%; animation-delay: calc(var(--loader-speed) * .16); }
.loader span:nth-child(3) { left: 58%; top: 20%; animation-delay: calc(var(--loader-speed) * .32); }
.loader span:nth-child(4) { left: 58%; top: 50%; animation-delay: calc(var(--loader-speed) * .48); }
.loader span:nth-child(5) { left: 33%; top: 65%; animation-delay: calc(var(--loader-speed) * .64); }
.loader span:nth-child(6) { left: 8%; top: 50%; animation-delay: calc(var(--loader-speed) * .8); }
.loader span:nth-child(7) { left: 8%; top: 20%; animation-delay: calc(var(--loader-speed) * .96); }
@keyframes comb { 0%, 100% { opacity: .16; transform: scale(.84); } 45% { opacity: 1; transform: scale(1); } }
